-- A checkout attempt ID is generated by the server and copied into Paddle custom_data.
-- It is the immutable identity that binds provider webhooks to one durable attempt.
-- Legacy rows may remain NULL, but neither legacy nor new identities may be rewritten.
CREATE OR REPLACE FUNCTION prevent_paddle_checkout_attempt_identity_change()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.attempt_id IS DISTINCT FROM OLD.attempt_id THEN
    RAISE EXCEPTION
      USING ERRCODE = '23514',
            MESSAGE = 'paddle checkout attempt identity is immutable';
  END IF;
  RETURN NEW;
END;
$function$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_trigger
    WHERE tgrelid = 'paddle_checkout_attempts'::regclass
      AND tgname = 'paddle_checkout_attempts_identity_immutable'
      AND NOT tgisinternal
  ) THEN
    CREATE TRIGGER paddle_checkout_attempts_identity_immutable
      BEFORE UPDATE OF attempt_id ON paddle_checkout_attempts
      FOR EACH ROW
      EXECUTE FUNCTION prevent_paddle_checkout_attempt_identity_change();
  END IF;
END $$;

COMMENT ON FUNCTION prevent_paddle_checkout_attempt_identity_change() IS
  'Prevents reassignment or clearing of the server-generated Paddle checkout attempt identity used to bind provider webhooks.';
